-- AUTO-GENERATED by pz_craft_loops/container_caps.py -- do not edit by hand.
-- Multi-tile builds from our packs act as ONE piece: pick-up and sledgehammer take every tile.
local PREFIXES = { "community.", "tikitown.", "worldessentials.tikitown.", "kbwcb." }
local RANGE = 5

local function isOurs(id)
    if type(id) ~= "string" then return false end
    for index = 1, #PREFIXES do
        if string.find(id, PREFIXES[index], 1, true) == 1 then return true end
    end
    return false
end

-- every object (incl. the given one first) sharing the KBW group id, or nil for single pieces
local function groupMembers(object)
    if not object or not object.hasModData or not object:hasModData() then return nil end
    local kbw = object:getModData().KBW
    if type(kbw) ~= "table" or type(kbw.groupId) ~= "string" then return nil end
    if (tonumber(kbw.partCount) or 1) < 2 or not isOurs(kbw.groupId) then return nil end
    local square = object:getSquare()
    if not square then return nil end
    local cell = getCell()
    local list = { object }
    local x0, y0, z = square:getX(), square:getY(), square:getZ()
    for dx = -RANGE, RANGE do
        for dy = -RANGE, RANGE do
            local sq = cell:getGridSquare(x0 + dx, y0 + dy, z)
            if sq then
                local objects = sq:getObjects()
                for index = 0, objects:size() - 1 do
                    local other = objects:get(index)
                    if other ~= object and other:hasModData() then
                        local okey = other:getModData().KBW
                        if type(okey) == "table" and okey.groupId == kbw.groupId then
                            list[#list + 1] = other
                        end
                    end
                end
            end
        end
    end
    if #list < 2 then return nil end
    return list
end

local function cheating(character)
    if ISMoveableDefinitions and ISMoveableDefinitions.cheat then return true end
    return character and character.isMovablesCheat and character:isMovablesCheat() or false
end

local function installPickup()
    if type(ISMoveableSpriteProps) ~= "table" then pcall(require, "Moveables/ISMoveableSpriteProps") end
    local P = ISMoveableSpriteProps
    if type(P) ~= "table" or type(P.canPickUpMoveable) ~= "function"
        or type(P.pickUpMoveable) ~= "function" or type(P.pickUpMoveableInternal) ~= "function" then
        return false
    end
    if P._kbwcbMultiPart then return true end
    P._kbwcbMultiPart = true

    -- the group of the clicked object when vanilla cannot treat it as one piece (no sprite grid)
    local function groupFor(self, square, object)
        if not object or not square then return nil end
        if self.isMultiSprite then
            local okGrid, grid = pcall(function() return self:getSpriteGridInfo(square, true) end)
            if okGrid and grid then return nil end
        end
        local okG, members = pcall(groupMembers, object)
        if okG then return members end
        return nil
    end

    local function propsFor(object)
        local okP, props = pcall(function() return ISMoveableSpriteProps.fromObject(object) end)
        if okP then return props end
        return nil
    end

    -- Part items of a group pick-up get vanilla's generic moveable look (box) instead of the tile
    -- art: vanilla does that for multi-sprite parts because their sprite has a grid; ours do not.
    local originalInstance = P.instanceItem
    if type(originalInstance) == "function" then
        P.instanceItem = function(self, spriteName)
            local item = originalInstance(self, spriteName)
            if item and self._kbwcbGeneric then
                pcall(function()
                    local blank = instanceItem("Moveables.Moveable")
                    if blank then
                        item:setTexture(blank:getTexture())
                        item:setWorldTexture(blank:getWorldTexture())
                    end
                end)
            end
            return item
        end
    end

    local originalCan = P.canPickUpMoveable
    P.canPickUpMoveable = function(self, character, square, object)
        local members = groupFor(self, square, object)
        if not members then return originalCan(self, character, square, object) end
        if cheating(character) then return originalCan(self, character, square, object) end
        for index = 1, #members do
            local member = members[index]
            local props = propsFor(member)
            if not props or not props.isMoveable then return false end
            if not props:canPickUpMoveableInternal(character, member:getSquare(), member, true) then
                return false
            end
        end
        return true
    end

    local originalPick = P.pickUpMoveable
    P.pickUpMoveable = function(self, character, square, createItem, forceAllow)
        local object, sprInstance = nil, nil
        local okF, o, s = pcall(function() return self:findOnSquare(square, self.spriteName) end)
        if okF then object, sprInstance = o, s end
        local members = nil
        if object and not sprInstance then members = groupFor(self, square, object) end
        if not members then return originalPick(self, character, square, createItem, forceAllow) end
        if not (forceAllow or cheating(character) or self:canPickUpMoveable(character, square, object)) then
            return false
        end
        local items = {}
        for index = 1, #members do
            local member = members[index]
            local props = propsFor(member)
            local msq = member:getSquare()
            local sprite = member:getSprite()
            if props and msq and sprite then
                local fluid = member.getFluidContainer and member:getFluidContainer() or nil
                if fluid then pcall(function() fluid:Empty() end) end
                -- flagged multi-sprite for the call so the part item lands on the floor (vanilla
                -- behaviour for multi-sprite pieces) instead of needing inventory room
                local was = props.isMultiSprite
                props.isMultiSprite = true
                props._kbwcbGeneric = true
                local okPick, res = pcall(function()
                    return props:pickUpMoveableInternal(character, msq, member, nil, sprite:getName(), createItem, forceAllow)
                end)
                props.isMultiSprite = was
                props._kbwcbGeneric = nil
                if okPick then items[#items + 1] = res
                else print("[KBWCommunity] MultiPart: pick-up of a part failed: " .. tostring(res)) end
            end
        end
        return items
    end
    print("[KBWCommunity] MultiPart: pick-up takes every tile of a multi-tile build")
    return true
end

local function installDestroy()
    if type(ISDestroyStuffAction) ~= "table" then pcall(require, "TimedActions/ISDestroyStuffAction") end
    local A = ISDestroyStuffAction
    if type(A) ~= "table" or type(A.complete) ~= "function" then return false end
    if A._kbwcbMultiPart then return true end
    A._kbwcbMultiPart = true
    local originalComplete = A.complete
    A.complete = function(self)
        local members = nil
        if self.item then
            local okG, found = pcall(groupMembers, self.item)
            if okG then members = found end
        end
        local result = originalComplete(self)
        if result and members then
            for index = 2, #members do
                local member = members[index]
                local sq = member:getSquare()
                if sq and member:getObjectIndex() ~= -1 then
                    pcall(function() member:dumpContentsInSquare() end)
                    if isClient() then
                        sledgeDestroy(member)
                    else
                        sq:transmitRemoveItemFromSquare(member)
                    end
                end
            end
        end
        return result
    end
    print("[KBWCommunity] MultiPart: sledgehammer destroys every tile of a multi-tile build")
    return true
end

local function installAll()
    local a = installPickup()
    local b = installDestroy()
    return a and b
end

if not installAll() then
    Events.OnGameStart.Add(installAll)
    if Events.OnServerStarted then Events.OnServerStarted.Add(installAll) end
end
